package grading.similarity;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Winnowing (Schleimer, Wilkerson and Aiken, 2003), the method behind MOSS. Every run of k tokens is
 * hashed, and from each window of w consecutive hashes the smallest is kept as a fingerprint. Two
 * sequences that share a run of at least w + k - 1 tokens are guaranteed to share a fingerprint.
 * Comparing fingerprints is fast, so it is used to screen every pair of students; it can over- or
 * under-estimate a little, because hashes can collide and only some runs are kept.
 */
final class WinnowingSimilarity implements SimilarityAlgorithm {

    private static final int HASH_BASE = 31;

    private final int kgramSize;
    private final int windowSize;

    WinnowingSimilarity(int kgramSize, int windowSize) {
        this.kgramSize = kgramSize;
        this.windowSize = windowSize;
    }

    @Override
    public String name() {
        return "Winnowing (k = " + kgramSize + ", w = " + windowSize + ")";
    }

    @Override
    public Comparison compare(List<Token> first, List<Token> second) {
        Map<Integer, Integer> firstPrints = fingerprints(first);
        Map<Integer, Integer> secondPrints = fingerprints(second);
        if (firstPrints.isEmpty() || secondPrints.isEmpty()) {
            return Comparison.none();
        }
        List<Comparison.Match> matches = new ArrayList<>();
        firstPrints.forEach((hash, position) -> {
            Integer other = secondPrints.get(hash);
            if (other != null) {
                int length = Math.min(kgramSize, Math.min(first.size() - position, second.size() - other));
                matches.add(new Comparison.Match(position, other, length));
            }
        });
        double score = 2.0 * matches.size() / (firstPrints.size() + secondPrints.size());
        return new Comparison(score, matches);
    }

    /** Each fingerprint's hash and the position of the first run of tokens it was taken from. */
    Map<Integer, Integer> fingerprints(List<Token> tokens) {
        int size = Math.min(kgramSize, tokens.size());
        if (size == 0) {
            return Map.of();
        }
        int[] hashes = new int[tokens.size() - size + 1];
        for (int start = 0; start < hashes.length; start++) {
            int hash = 0;
            for (int offset = 0; offset < size; offset++) {
                hash = hash * HASH_BASE + tokens.get(start + offset).kind().hashCode();
            }
            hashes[start] = hash;
        }
        Map<Integer, Integer> fingerprints = new LinkedHashMap<>();
        int window = Math.min(windowSize, hashes.length);
        for (int start = 0; start + window <= hashes.length; start++) {
            // The rightmost smallest hash, so a window that slides past the same minimum keeps it once.
            int chosen = start;
            for (int position = start; position < start + window; position++) {
                if (hashes[position] <= hashes[chosen]) {
                    chosen = position;
                }
            }
            fingerprints.putIfAbsent(hashes[chosen], chosen);
        }
        return fingerprints;
    }
}
